//! Rust code generated from a checked interface.
//!
//! [`interface_module`] is the interface crate's half: types, the trait a
//! component implements, call decoding and the export macro.
//! [`client_module`] is the client crate's half: typed functions that encode
//! a call, make it through the function's Invocation and decode the answer.
//! Both are a module named after the interface, to be included at the root
//! of their crate.

use {
    crate::{
        ast::{Field, Method, TypeKind, TypeReference},
        check::{Checked, Resolved, camel_case, export_name},
    },
    proc_macro2::{Ident, Literal, Span, TokenStream},
    quote::quote,
};

/// Where the generated code finds the runtime support crate.
const RUNTIME_CRATE: &str = "libmeddle_runtime";

fn ident(name: &str) -> Ident {
    Ident::new(name, Span::call_site())
}

fn camel_ident(name: &str) -> Ident {
    ident(&camel_case(name))
}

fn index_literal(index: usize) -> Literal {
    Literal::usize_unsuffixed(index)
}

fn word_literal(index: usize) -> Literal {
    Literal::u64_unsuffixed(u64::try_from(index).unwrap_or(u64::MAX))
}

/// `#[doc = "..."]` for each documentation line.
fn docs(lines: &[String]) -> TokenStream {
    let lines = lines.iter().map(|line| format!(" {line}"));
    quote! { #( #[doc = #lines] )* }
}

/// `&words` at offset zero, `&words[offset..]` elsewhere.
fn words_from(words: &TokenStream, offset: usize, mutable: bool) -> TokenStream {
    let mutability = if mutable { quote!(mut) } else { quote!() };
    if offset == 0 {
        quote! { &#mutability #words }
    } else {
        let offset = index_literal(offset);
        quote! { &#mutability #words[#offset..] }
    }
}

/// Render generated items as formatted source.
fn render(source_name: &str, tokens: &TokenStream) -> String {
    let header = format!("// Generated by meddler from {source_name}. Do not edit.\n\n");
    match syn::parse2::<syn::File>(tokens.clone()) {
        Ok(file) => header + &prettyplease::unparse(&file),
        // Unparseable output is a generator bug; keep it readable for the
        // compiler error that follows.
        Err(_) => header + &tokens.to_string(),
    }
}

struct Emitter<'checked, 'interface> {
    checked: &'checked Checked<'interface>,
    runtime: TokenStream,
}

impl Emitter<'_, '_> {
    /// The Rust type of `ty`.
    fn rust_type(&self, ty: &TypeReference) -> TokenStream {
        let runtime = &self.runtime;
        if ty.reference {
            return quote! { #runtime::IoRec };
        }
        match self.checked.resolve(&ty.name.text) {
            Some(Resolved::Builtin(builtin)) => {
                let name = ident(builtin.rust_name());
                quote! { #name }
            }
            Some(Resolved::Defined(_)) | None => {
                let name = camel_ident(&ty.name.text);
                quote! { #name }
            }
        }
    }

    /// Statements storing `fields` (read through `access`) at word offsets
    /// from zero in `words`.
    fn store_fields(
        &self,
        fields: &[Field],
        words: &TokenStream,
        access: impl Fn(&Ident) -> TokenStream,
    ) -> TokenStream {
        let runtime = &self.runtime;
        let mut offset = 0;
        let mut statements = TokenStream::new();
        for field in fields {
            let name = ident(&field.name.text);
            let value = access(&name);
            let target = words_from(words, offset, true);
            statements.extend(quote! { #runtime::Words::store(#value, #target); });
            offset += self.checked.words_of(&field.ty);
        }
        statements
    }

    /// `name: Words::load(&words[offset..])?,` for each field.
    fn load_fields(&self, fields: &[Field], words: &TokenStream) -> TokenStream {
        let runtime = &self.runtime;
        let mut offset = 0;
        let mut initializers = TokenStream::new();
        for field in fields {
            let name = ident(&field.name.text);
            let source = words_from(words, offset, false);
            initializers.extend(quote! { #name: #runtime::Words::load(#source)?, });
            offset += self.checked.words_of(&field.ty);
        }
        initializers
    }

    fn type_definitions(&self) -> TokenStream {
        let runtime = &self.runtime;
        let mut items = TokenStream::new();
        for definition in &self.checked.interface().types {
            let doc = docs(&definition.doc);
            let name = camel_ident(&definition.name.text);
            match &definition.kind {
                TypeKind::Alias(target) => {
                    let target = self.rust_type(target);
                    items.extend(quote! { #doc pub type #name = #target; });
                }
                TypeKind::Enum(values) => {
                    let variants: Vec<Ident> = values
                        .iter()
                        .map(|value| camel_ident(&value.text))
                        .collect();
                    let indices = (0..values.len()).map(word_literal);
                    let load_indices = indices.clone();
                    items.extend(quote! {
                        #doc
                        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
                        pub enum #name { #( #variants ),* }

                        impl #runtime::Words for #name {
                            const COUNT: usize = 1;

                            fn store(&self, words: &mut [u64]) {
                                words[0] = match self { #( Self::#variants => #indices ),* };
                            }

                            fn load(words: &[u64]) -> Option<Self> {
                                match words[0] {
                                    #( #load_indices => Some(Self::#variants), )*
                                    _ => None,
                                }
                            }
                        }
                    });
                }
                TypeKind::Record(fields) => {
                    let field_docs = fields.iter().map(|field| docs(&field.doc));
                    let field_names = fields.iter().map(|field| ident(&field.name.text));
                    let field_types = fields.iter().map(|field| self.rust_type(&field.ty));
                    let count = index_literal(self.checked.words_of_fields(fields));
                    let words = quote!(words);
                    let (store, store_parameter) = if fields.is_empty() {
                        (TokenStream::new(), quote!(_))
                    } else {
                        (
                            self.store_fields(fields, &words, |field| quote! { &self.#field }),
                            words.clone(),
                        )
                    };
                    let load_parameter = if fields.is_empty() {
                        quote!(_)
                    } else {
                        words.clone()
                    };
                    let load = self.load_fields(fields, &words);
                    items.extend(quote! {
                        #doc
                        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
                        pub struct #name { #( #field_docs pub #field_names: #field_types, )* }

                        impl #runtime::Words for #name {
                            const COUNT: usize = #count;

                            fn store(&self, #store_parameter: &mut [u64]) { #store }

                            fn load(#load_parameter: &[u64]) -> Option<Self> {
                                Some(Self { #load })
                            }
                        }
                    });
                }
            }
        }
        items
    }

    /// The `Exception` enum, if the interface declares exceptions.
    fn exceptions(&self) -> TokenStream {
        let exceptions = &self.checked.interface().exceptions;
        if exceptions.is_empty() {
            return TokenStream::new();
        }
        let runtime = &self.runtime;
        let mut variants = TokenStream::new();
        let mut answers = TokenStream::new();
        let mut decodes = TokenStream::new();
        let words = quote!(words);
        for (index, exception) in exceptions.iter().enumerate() {
            let doc = docs(&exception.doc);
            let name = camel_ident(&exception.name.text);
            let index_word = word_literal(index);
            let outcome = word_literal(index + 1);
            if exception.fields.is_empty() {
                variants.extend(quote! { #doc #name, });
                answers.extend(quote! { Self::#name => #runtime::exception(#index_word, 0), });
                decodes.extend(quote! { #outcome => (field == 0).then_some(Self::#name), });
            } else {
                let field_docs = exception.fields.iter().map(|field| docs(&field.doc));
                let field_names: Vec<Ident> = exception
                    .fields
                    .iter()
                    .map(|field| ident(&field.name.text))
                    .collect();
                let field_types = exception
                    .fields
                    .iter()
                    .map(|field| self.rust_type(&field.ty));
                let store =
                    self.store_fields(&exception.fields, &words, |field| quote! { &#field });
                let load = self.load_fields(&exception.fields, &words);
                variants.extend(
                    quote! { #doc #name { #( #field_docs #field_names: #field_types ),* }, },
                );
                answers.extend(quote! {
                    Self::#name { #( #field_names ),* } => {
                        let mut words = [0; 1];
                        #store
                        #runtime::exception(#index_word, words[0])
                    }
                });
                decodes.extend(quote! { #outcome => Some(Self::#name { #load }), });
            }
        }
        quote! {
            /// The exceptions functions of this interface raise.
            #[derive(Clone, Copy, Debug, PartialEq, Eq)]
            pub enum Exception { #variants }

            impl Exception {
                /// The answer of a function raising this exception.
                #[doc(hidden)]
                pub fn answer(self) -> #runtime::PpcResult {
                    match self { #answers }
                }

                /// The exception a function answered with `outcome` and `field`.
                pub fn from_answer(outcome: u64, field: u64) -> Option<Self> {
                    let words = [field];
                    match outcome {
                        #decodes
                        _ => None,
                    }
                }
            }
        }
    }

    /// The Rust result type of `method`: its one result (or `()`), in a
    /// `Result` when it raises exceptions.
    fn result_type(&self, method: &Method) -> Option<TokenStream> {
        let value = method
            .results
            .first()
            .map(|result| self.rust_type(&result.ty));
        match (value, method.raises.is_empty()) {
            (None, true) => None,
            (Some(value), true) => Some(value),
            (value, false) => {
                let value = value.unwrap_or_else(|| quote!(()));
                Some(quote! { Result<#value, Exception> })
            }
        }
    }

    fn parameters(&self, method: &Method) -> Vec<TokenStream> {
        method
            .parameters
            .iter()
            .map(|parameter| {
                let name = ident(&parameter.name.text);
                let ty = self.rust_type(&parameter.ty);
                quote! { #name: #ty }
            })
            .collect()
    }

    fn component_trait(&self) -> TokenStream {
        let interface = self.checked.interface();
        let doc = docs(&interface.doc);
        let trait_name = camel_ident(&interface.name.text);
        let methods = interface.methods.iter().map(|method| {
            let doc = docs(&method.doc);
            let name = ident(&method.name.text);
            let parameters = self.parameters(method);
            let result = self.result_type(method).map(|result| quote! { -> #result });
            quote! { #doc fn #name( #( #parameters ),* ) #result; }
        });
        quote! {
            #doc
            ///
            /// A component implements this trait and exports it with the
            /// interface crate's export macro.
            pub trait #trait_name {
                /// Runs first in every call, before the arguments are decoded:
                /// set up what the component needs to answer, such as its
                /// `Thread.Return` key.
                fn enter() {}

                #( #methods )*
            }
        }
    }

    /// `__dispatch_<method>`: decode the arguments, call the implementation,
    /// encode its answer.
    fn dispatchers(&self) -> TokenStream {
        let runtime = &self.runtime;
        let trait_name = camel_ident(&self.checked.interface().name.text);
        let mut items = TokenStream::new();
        for method in &self.checked.interface().methods {
            let name = ident(&method.name.text);
            let dispatcher = ident(&format!("__dispatch_{}", method.name.text));
            let used = index_literal(self.checked.words_of_fields(&method.parameters));
            let arguments = quote!(arguments);
            let mut offset = 0;
            let mut decode = TokenStream::new();
            for parameter in &method.parameters {
                let parameter_name = ident(&parameter.name.text);
                let ty = self.rust_type(&parameter.ty);
                let source = words_from(&arguments, offset, false);
                decode.extend(quote! {
                    let Some(#parameter_name) = <#ty as #runtime::Words>::load(#source) else {
                        return #runtime::malformed();
                    };
                });
                offset += self.checked.words_of(&parameter.ty);
            }
            let parameter_names = method
                .parameters
                .iter()
                .map(|parameter| ident(&parameter.name.text));
            let call = quote! { Implementation::#name( #( #parameter_names ),* ) };
            let answer_value = quote! {
                let mut words = [0; 1];
                #runtime::Words::store(&result, &mut words);
                #runtime::ok(words[0])
            };
            let answer = match (method.results.is_empty(), method.raises.is_empty()) {
                (true, true) => quote! { #call; #runtime::ok(0) },
                (false, true) => quote! { let result = #call; #answer_value },
                (true, false) => quote! {
                    match #call {
                        Ok(()) => #runtime::ok(0),
                        Err(exception) => exception.answer(),
                    }
                },
                (false, false) => quote! {
                    match #call {
                        Ok(result) => { #answer_value }
                        Err(exception) => exception.answer(),
                    }
                },
            };
            items.extend(quote! {
                #[doc(hidden)]
                pub fn #dispatcher<Implementation: #trait_name>(
                    arguments: [u64; #runtime::ARGUMENT_WORDS],
                ) -> #runtime::PpcResult {
                    Implementation::enter();
                    if !#runtime::unused_words_are_zero(&arguments, #used) {
                        return #runtime::malformed();
                    }
                    #decode
                    #answer
                }
            });
        }
        items
    }

    fn export_macro(&self) -> TokenStream {
        let interface = self.checked.interface();
        let module = ident(&interface.name.text);
        let macro_name = ident(&format!("{}_export", interface.name.text));
        let trait_name = camel_ident(&interface.name.text);
        let doc = format!(
            " Export every function of `{}`, implemented by the given type of \
             [`{module}::{trait_name}`], as a PPC entry named `{}_<function>`.",
            interface.name.text, interface.name.text
        );
        let entries = interface.methods.iter().map(|method| {
            let dispatcher = ident(&format!("__dispatch_{}", method.name.text));
            let entry = ident(&export_name(&interface.name.text, &method.name.text));
            quote! {
                $crate::#module::__runtime::export_function!(
                    #entry,
                    $crate::#module::#dispatcher::<$implementation>
                );
            }
        });
        quote! {
            #[doc = #doc]
            #[macro_export]
            macro_rules! #macro_name {
                ($implementation:ty) => { #( #entries )* };
            }
        }
    }

    fn client(&self, interface_crate: &str) -> TokenStream {
        let runtime = &self.runtime;
        let interface = self.checked.interface();
        let module = ident(&interface.name.text);
        let interface_crate = ident(interface_crate);
        let has_exceptions = !interface.exceptions.is_empty();
        let mut reexports: Vec<Ident> = vec![ident("TYPE_CODE")];
        reexports.extend(
            interface
                .types
                .iter()
                .map(|definition| camel_ident(&definition.name.text)),
        );
        if has_exceptions {
            reexports.push(ident("Exception"));
        }
        let exception_variant = has_exceptions.then(|| {
            quote! {
                /// The function raised an exception.
                Exception(Exception),
            }
        });
        let binding_fields = interface.methods.iter().map(|method| {
            let doc = docs(&method.doc);
            let name = ident(&method.name.text);
            quote! { #doc pub #name: Option<#runtime::Binding>, }
        });
        let functions = interface
            .methods
            .iter()
            .map(|method| self.client_function(method));
        let assignments = interface.methods.iter().enumerate().map(|(index, method)| {
            let name = ident(&method.name.text);
            let index = word_literal(index);
            quote! { #index => bindings.#name = Some(record.binding()), }
        });
        let interface_doc = docs(&interface.doc);
        quote! {
            #interface_doc
            pub mod #module {
                #[doc(hidden)]
                pub use ::#interface_crate::#module::__runtime;
                pub use ::#interface_crate::#module::{ #( #reexports ),* };

                /// The functions this client may call. A function without a
                /// binding was not granted to it.
                #[derive(Default)]
                #[allow(clippy::struct_field_names)]
                pub struct Bindings { #( #binding_fields )* }

                impl Bindings {
                    /// The bindings `imports` grant for this interface
                    /// version, from the client's init record.
                    pub fn from_imports(imports: &[#runtime::ImportRecord]) -> Self {
                        let mut bindings = Self::default();
                        for record in imports.iter().filter(|record| record.type_code == TYPE_CODE) {
                            match record.function {
                                #( #assignments )*
                                _ => {}
                            }
                        }
                        bindings
                    }
                }

                /// Why a call did not return a result.
                #[derive(Clone, Copy, Debug, PartialEq, Eq)]
                pub enum Error {
                    #exception_variant
                    /// This client holds no Invocation for the function.
                    NotGranted,
                    /// The component could not decode the arguments.
                    Malformed,
                    /// The component answered with words this interface does not define.
                    UnexpectedAnswer { outcome: u64, word: u64 },
                    /// `Invocation.Call` failed: its status and two detail words.
                    Call { status: u64, detail: [u64; 2] },
                }

                fn call_error(error: #runtime::CapError) -> Error {
                    let (status, detail1, detail2) = error.code();
                    Error::Call { status, detail: [detail1, detail2] }
                }

                /// Typed calls to the functions of this interface.
                pub struct Client {
                    bindings: Bindings,
                    stacks: #runtime::ExclusiveStacks,
                }

                impl Client {
                    /// A client calling through `bindings`, whose target
                    /// stacks `stacks` proves are the calling Thread's alone.
                    pub const fn new(bindings: Bindings, stacks: #runtime::ExclusiveStacks) -> Self {
                        Self { bindings, stacks }
                    }

                    #( #functions )*
                }
            }
        }
    }

    fn client_function(&self, method: &Method) -> TokenStream {
        let runtime = &self.runtime;
        let doc = docs(&method.doc);
        let name = ident(&method.name.text);
        let parameters = self.parameters(method);
        let value = method
            .results
            .first()
            .map(|result| self.rust_type(&result.ty));
        let return_value = value.clone().unwrap_or_else(|| quote!(()));
        let arguments = quote!(arguments);
        let store = self.store_fields(&method.parameters, &arguments, |field| quote! { &#field });
        let declare_arguments = if method.parameters.is_empty() {
            quote! { let arguments = [0; #runtime::ARGUMENT_WORDS]; }
        } else {
            quote! { let mut arguments = [0; #runtime::ARGUMENT_WORDS]; #store }
        };
        let success = match &value {
            Some(value) => quote! {
                #runtime::OUTCOME_OK => <#value as #runtime::Words>::load(&[word])
                    .ok_or(Error::UnexpectedAnswer { outcome, word }),
            },
            None => quote! { #runtime::OUTCOME_OK if word == 0 => Ok(()), },
        };
        let other = if method.raises.is_empty() {
            quote! { _ => Err(Error::UnexpectedAnswer { outcome, word }), }
        } else {
            let patterns: Vec<TokenStream> = method
                .raises
                .iter()
                .map(|raised| {
                    let variant = camel_ident(&raised.text);
                    let has_fields =
                        self.checked
                            .exception_index(&raised.text)
                            .is_some_and(|index| {
                                !self.checked.interface().exceptions[index].fields.is_empty()
                            });
                    if has_fields {
                        quote! { Exception::#variant { .. } }
                    } else {
                        quote! { Exception::#variant }
                    }
                })
                .collect();
            // A single alternative takes no parentheses.
            let raised = if let [only] = patterns.as_slice() {
                only.clone()
            } else {
                quote! { ( #( #patterns )|* ) }
            };
            quote! {
                _ => Err(match Exception::from_answer(outcome, word) {
                    Some(exception @ #raised) => Error::Exception(exception),
                    _ => Error::UnexpectedAnswer { outcome, word },
                }),
            }
        };
        quote! {
            #doc
            pub fn #name(&self, #( #parameters ),*) -> Result<#return_value, Error> {
                let binding = self.bindings.#name.as_ref().ok_or(Error::NotGranted)?;
                #declare_arguments
                let (outcome, word) = binding.call(&self.stacks, arguments).map_err(call_error)?;
                match outcome {
                    #success
                    #runtime::OUTCOME_MALFORMED => Err(Error::Malformed),
                    #other
                }
            }
        }
    }
}

/// The interface crate's module for `checked`, read from `source_name`.
pub fn interface_module(checked: &Checked<'_>, source_name: &str) -> String {
    let runtime_crate = ident(RUNTIME_CRATE);
    let emitter = Emitter {
        checked,
        runtime: quote!(__runtime),
    };
    let interface = checked.interface();
    let module = ident(&interface.name.text);
    let doc = docs(&interface.doc);
    let type_code: TokenStream = format!("0x{:016x}", checked.type_code())
        .parse()
        .unwrap_or_else(|_| quote!(0));
    let types = emitter.type_definitions();
    let exceptions = emitter.exceptions();
    let component_trait = emitter.component_trait();
    let dispatchers = emitter.dispatchers();
    let export_macro = emitter.export_macro();
    render(
        source_name,
        &quote! {
            #doc
            pub mod #module {
                #[doc(hidden)]
                pub use ::#runtime_crate as __runtime;

                /// Fingerprint of this interface version.
                pub const TYPE_CODE: u64 = #type_code;

                #types
                #exceptions
                #component_trait
                #dispatchers
            }

            #export_macro
        },
    )
}

/// The client crate's module for `checked`, read from `source_name`, whose
/// interface crate is called `interface_crate`.
pub fn client_module(checked: &Checked<'_>, source_name: &str, interface_crate: &str) -> String {
    let emitter = Emitter {
        checked,
        runtime: quote!(__runtime),
    };
    render(source_name, &emitter.client(interface_crate))
}
